import Foundation

extension LegalGuides {
    static let authorities = DirectoryGuide(
        cardSummary: .init(ukrainian: "Заява, дата вручення, скарга та бездіяльність органу", german: "Antrag, Zustellung, Beschwerde und Untätigkeit"),
        introduction: .init(ukrainian: "Для взаємодії з установою зберігайте докази подання та вручення. Телефонна розмова не зупиняє строк оскарження.", german: "Bei Behördenkontakten Einbringungs- und Zustellnachweise aufbewahren. Ein Telefonat stoppt keine Rechtsmittelfrist."),
        sections: [
            .init("file", "tray.and.arrow.up", "Подайте заяву доказово", "Antrag nachweisbar einbringen", "Знайдіть орган, що вирішує саме вашу справу, і попросіть перелік документів, спосіб подання та можливі збори. У заяві вкажіть ім’я, контакт, номер справи за наявності й конкретне прохання. Збережіть копію, квитанцію про відправлення або підтвердження онлайн-подачі; окремо запишіть дату, коли орган отримав документи.", "Zuständige Stelle für den konkreten Fall und Unterlagen, Einbringungsweg sowie Gebühren klären. Im Antrag Name, Kontakt, gegebenenfalls Geschäftszahl und konkretes Begehren nennen. Kopie, Postbeleg oder Online-Eingangsbestätigung sichern; Eingangsdatum bei der Behörde gesondert notieren.", source: appeal),
            .init("decision", "doc.text.magnifyingglass", "Розберіть Bescheid", "Bescheid lesen", "Перевірте Spruch: що дозволено, відмовлено або наказано, кому й від якої дати. Збережіть усі сторінки, додатки, конверт або доказ електронного вручення. У Rechtsmittelbelehrung знайдіть спосіб, орган і строк скарги; якщо текст незрозумілий, терміново зверніться по допомогу з перекладом і правом.", "Im Spruch prüfen, was bewilligt, abgelehnt oder angeordnet wird, für wen und ab wann. Alle Seiten, Beilagen, Umschlag oder elektronischen Zustellnachweis sichern. In der Rechtsmittelbelehrung Weg, Stelle und Frist suchen; bei Verständnisproblemen sofort Sprach- und Rechtsberatung holen.", source: appeal),
            .init("deadline", "calendar", "Не пропустіть строк скарги", "Beschwerdefrist nicht verpassen", "Для багатьох адміністративних Bescheid загальний строк — чотири тижні після вручення. У справах притулку можливі строки один тиждень, десять днів або два тижні; для податків існує окреме правило. Читайте саме своє рішення і звертайтеся за консультацією одразу. Не виходьте з того, що лист із питанням чи телефонний дзвінок продовжить строк.", "Für viele Verwaltungsbescheide gelten grundsätzlich vier Wochen ab Zustellung. In Asylverfahren können eine Woche, zehn Tage oder zwei Wochen gelten; Abgaben folgen einer eigenen Regel. Immer den eigenen Bescheid lesen und sofort beraten lassen. Ein Nachfrageschreiben oder Telefonat verlängert die Frist nicht automatisch.", source: asylum),
            .init("complaint", "arrow.uturn.backward", "Скаргу подавайте до органу, який вирішив справу", "Beschwerde bei der entscheidenden Behörde einbringen", "Зазвичай Bescheidbeschwerde подають органу, який видав рішення, а не безпосередньо суду. Назвіть оскаржуваний Bescheid, поясніть, що вважаєте неправильним, і якого результату просите. Збережіть доказ своєчасного подання. Скарга зазвичай має зупиняючу дію, але є винятки; перевірте це для своєї справи до будь-яких дій.", "Die Bescheidbeschwerde wird grundsätzlich bei der erlassenden Behörde eingebracht, nicht direkt beim Gericht. Angefochtenen Bescheid, behaupteten Fehler und begehrte Änderung nennen. Fristgerechte Einbringung belegen. Eine Beschwerde hat grundsätzlich aufschiebende Wirkung, mit Ausnahmen; Wirkung im eigenen Fall vor weiteren Schritten prüfen.", source: appeal),
            .init("next", "arrow.right", "Якщо орган відповів на скаргу", "Nach einer Beschwerdevorentscheidung", "Орган може сам переглянути рішення. Якщо отримали Beschwerdevorentscheidung і не погоджуєтеся, перевірте можливість Vorlageantrag: за загальним правилом це два тижні після вручення, щоб справу розглянув адміністративний суд. Не плутайте його з початковою скаргою; збережіть обидва рішення й докази подання.", "Die Behörde kann zunächst selbst neu entscheiden. Sind Sie mit einer Beschwerdevorentscheidung nicht einverstanden, Vorlageantrag prüfen: grundsätzlich binnen zwei Wochen ab Zustellung, damit das Verwaltungsgericht befasst wird. Nicht mit der ursprünglichen Beschwerde verwechseln; beide Entscheidungen und Nachweise sichern.", source: appeal),
            .init("delay", "clock.arrow.circlepath", "Якщо відповіді немає", "Wenn die Behörde nicht entscheidet", "Перевірте встановлений законом строк рішення та чи документи були отримані повністю. Якщо орган порушив обов’язок вирішити справу, можлива Säumnisbeschwerde; загальне правило — після шести місяців, але спеціальний строк може бути іншим. Зберіть підтвердження дати подання та листування й попросіть правника перевірити передумови такої скарги.", "Gesetzliche Entscheidungsfrist und vollständigen Eingang der Unterlagen prüfen. Bei verletzter Entscheidungspflicht kann eine Säumnisbeschwerde möglich sein; grundsätzlich nach sechs Monaten, bei Sonderregel anders. Eingangsdatum und Korrespondenz belegen und Voraussetzungen der Beschwerde rechtlich prüfen lassen.", source: appeal),
            .init("ombudsman", "person.crop.rectangle", "Скарга на роботу установи", "Beschwerde über Verwaltungsmissstand", "Якщо проблема стосується роботи австрійського органу, Volksanwaltschaft приймає звернення безкоштовно незалежно від громадянства. Опишіть орган, номер справи, події й додайте копії листування. Це перевірка адміністрації, а не заміна Bescheidbeschwerde: паралельно дотримуйтеся строку юридичного оскарження.", "Bei Problemen mit einer österreichischen Behörde nimmt die Volksanwaltschaft Beschwerden unabhängig von der Staatsangehörigkeit kostenlos entgegen. Behörde, Geschäftszahl und Ablauf nennen und Kopien beilegen. Das ist Verwaltungskontrolle, kein Ersatz für die Bescheidbeschwerde: deren Frist parallel beachten.", source: ombudsman)
        ], sources: [appeal, asylum, ombudsman]
    )
}
